67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(LocalDate.now());
116	        }
117	        long ownersRegisteredToday = this.clinicService.findAllOwners().stream()
118	            .filter(existing -> LocalDate.now().equals(existing.getRegistrationDate()))
119	            .count();
120	        if (ownersRegisteredToday >= 20) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        if (this.clinicService.existsIdenticalOwner(owner)
124	            || this.clinicService.existsOwnerWithTelephone(owner.getTelephone())
125	            || this.clinicService.existsOwnerWithEmail(owner.getEmail())) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        long namesakeCount = this.clinicService.findAllOwners().stream()
129	            .filter(existing -> existing.getLastName() != null
130	                && existing.getLastName().equals(owner.getLastName()))
131	            .count();
132	        owner.setNamesakeCount((int) namesakeCount);
133	        int ownersBefore = this.clinicService.findAllOwners().size();
134	        owner.setMembershipNumber(ownersBefore + 1);
135	        owner.setMembershipTier(ownersBefore < 100 ? "FOUNDING" : "STANDARD");
136	        owner.setCity(resolveCityName(owner.getCity()));
137	        long ownersInCity = this.clinicService.findAllOwners().stream()
138	            .filter(existing -> existing.getCity() != null
139	                && existing.getCity().equalsIgnoreCase(owner.getCity()))
140	            .count();
141	        if (ownersInCity >= 8) {
142	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
143	        }
144	        owner.setCustomerCode(String.format("%s-%04d",
145	            owner.getCity().toUpperCase(Locale.ROOT), ownersInCity + 1));
146	        boolean sharesHousehold = this.clinicService.findAllOwners().stream()
147	            .anyMatch(existing -> existing.getAddress() != null
148	                && existing.getAddress().equals(owner.getAddress())
149	                && existing.getCity() != null
150	                && existing.getCity().equalsIgnoreCase(owner.getCity()));
151	        owner.setSharesHousehold(sharesHousehold);
152	        owner.setLocality(isMostCommonCity(owner.getCity()) ? "local" : "remote");
153	        this.clinicService.saveOwner(owner);
154	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
155	        String user = authentication != null ? authentication.getName() : "anonymous";
156	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
157	            user, owner.getId(), owner.getMembershipNumber());
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    /**
165	     * Resolves the city name to store for a newly created owner. If another owner already
166	     * lives in the same city (compared case-insensitively), that owner's exact spelling of
167	     * the city is reused so a city keeps a single canonical spelling. Otherwise the supplied
168	     * city is title-cased (each word capitalised, remaining letters lower-cased).
169	     *
170	     * @param city the raw city supplied for the new owner (may be {@code null})
171	     * @return the city name to store, or {@code null} if {@code city} is {@code null}
172	     */
173	    private String resolveCityName(String city) {
174	        if (city == null) {
175	            return null;
176	        }
177	        return this.clinicService.findAllOwners().stream()
178	            .map(Owner::getCity)
179	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
180	            .findFirst()
181	            .orElseGet(() -> toTitleCase(city));
182	    }
183	
184	    /**
185	     * Title-cases a city name: the first letter of every whitespace-separated word is
186	     * upper-cased and the remaining letters are lower-cased, e.g. {@code "new  YORK"}
187	     * becomes {@code "New  York"}. Whitespace is preserved as-is.
188	     *
189	     * @param city the city name to title-case
190	     * @return the title-cased city name
191	     */
192	    private static String toTitleCase(String city) {
193	        StringBuilder result = new StringBuilder(city.length());
194	        boolean startOfWord = true;
195	        for (int i = 0; i < city.length(); i++) {
196	            char c = city.charAt(i);
197	            if (Character.isWhitespace(c)) {
198	                startOfWord = true;
199	                result.append(c);
200	            } else {
201	                result.append(startOfWord
202	                    ? Character.toTitleCase(c)
203	                    : Character.toLowerCase(c));
204	                startOfWord = false;
205	            }
206	        }
207	        return result.toString();
208	    }
209	
210	    /**
211	     * Determines whether the supplied city is the single most common city among the owners that
212	     * already exist. Cities are compared case-insensitively. A city qualifies only when strictly
213	     * more existing owners live there than in any other city; if the city is absent, tied for the
214	     * lead, or there are no existing owners at all, it is not the single most common city.
215	     *
216	     * @param city the (already canonicalised) city of the owner being created (may be {@code null})
217	     * @return {@code true} if {@code city} is uniquely the most common existing city
218	     */
219	    private boolean isMostCommonCity(String city) {
220	        if (city == null) {
221	            return false;
222	        }
223	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
224	            .map(Owner::getCity)
225	            .filter(existing -> existing != null)
226	            .collect(Collectors.groupingBy(c -> c.toLowerCase(Locale.ROOT), Collectors.counting()));
227	        long max = countsByCity.values().stream().mapToLong(Long::longValue).max().orElse(0L);
228	        if (max == 0L) {
229	            return false;
230	        }
231	        long numberOfCitiesWithMax = countsByCity.values().stream()
232	            .filter(count -> count == max)
233	            .count();
234	        if (numberOfCitiesWithMax != 1L) {
235	            return false;
236	        }
237	        Long cityCount = countsByCity.get(city.toLowerCase(Locale.ROOT));
238	        return cityCount != null && cityCount == max;
239	    }
240	
