243	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        currentOwner.setAddress(ownerFieldsDto.getAddress());
249	        currentOwner.setCity(ownerFieldsDto.getCity());
250	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
251	        currentOwner.setLastName(ownerFieldsDto.getLastName());
252	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
253	        this.clinicService.saveOwner(currentOwner);
254	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
255	    }
256	
