261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        this.clinicService.deleteOwner(owner);
266	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
267	    }
