269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner == null) {
274	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	        }
276	        HttpHeaders headers = new HttpHeaders();
277	        Pet pet = petMapper.toPet(petFieldsDto);
278	        owner.setId(ownerId);
279	        pet.setOwner(owner);
280	        pet.getType().setName(null);
281	        this.clinicService.savePet(pet);
282	        PetDto petDto = petMapper.toPetDto(pet);
283	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
284	            .buildAndExpand(pet.getId()).toUri());
285	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
291	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
292	        if (currentOwner != null) {
293	            Pet currentPet = this.clinicService.findPetById(petId);
294	            if (currentPet != null) {
295	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
296	                currentPet.setName(petFieldsDto.getName());
297	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
298	                this.clinicService.savePet(currentPet);
299	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
300	            }
301	        }
302	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
303	    }
