306	    @Override
307	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
308	        HttpHeaders headers = new HttpHeaders();
309	        Visit visit = visitMapper.toVisit(visitFieldsDto);
310	        Pet pet = new Pet();
311	        pet.setId(petId);
312	        visit.setPet(pet);
313	        this.clinicService.saveVisit(visit);
314	        VisitDto visitDto = visitMapper.toVisitDto(visit);
315	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
316	            .buildAndExpand(visit.getId()).toUri());
317	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
318	    }
