320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
324	        Owner owner = this.clinicService.findOwnerById(ownerId);
325	        if (owner != null) {
326	            Pet pet = owner.getPet(petId);
327	            if (pet != null) {
328	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
329	            }
330	        }
331	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
332	    }
